effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmNoise(vec2 p){
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(gmHash(i), gmHash(i + vec2(1.0, 0.0)), u.x),
             mix(gmHash(i + vec2(0.0, 1.0)), gmHash(i + vec2(1.0, 1.0)), u.x), u.y);
}
void main(){
  vec2 uv = acScreenNorm;
  float n1 = gmNoise(uv * 30.0);
  float n2 = gmNoise(uv * 30.0 + 11.0);
  vec2 wuv = uv + (vec2(n1, n2) - 0.5) * warp;
  vec4 src = texture2DCv(inputImg.texture, wuv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 soft = c;
  float px = 1.5 / max(acScreenSize.y, 1.0);
  soft += texture2DCv(inputImg.texture, wuv + vec2(px, 0.0)).rgb / max(texture2DCv(inputImg.texture, wuv + vec2(px, 0.0)).a, 1e-4);
  soft += texture2DCv(inputImg.texture, wuv - vec2(px, 0.0)).rgb / max(texture2DCv(inputImg.texture, wuv - vec2(px, 0.0)).a, 1e-4);
  soft /= 3.0;
  float n = max(steps, 2.0) - 1.0;
  vec3 flat = floor(soft * n + 0.5) / n;
  vec3 col = mix(c, flat, mixAmt);
  col *= mix(1.0, 0.85 + 0.3 * gmNoise(uv * 400.0), bleed);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
